#!/usr/bin/env python3
"""D08 - sqlite3 模块替代 sqlite3 CLI，列出所有表与 schema。"""
import sqlite3, os, json
from pathlib import Path

db_path = Path('tmpPlan/agent-test/d08/laew_demo.db')

# 造演示库
try:
    if db_path.exists():
        db_path.unlink()
    conn = sqlite3.connect(str(db_path))
    conn.executescript('''
        CREATE TABLE providers(
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL,
            protocol TEXT DEFAULT 'openai',
            is_active INTEGER DEFAULT 0
        );
        INSERT INTO providers VALUES(1, 'demo', 'openai', 1);
        INSERT INTO providers VALUES(2, 'mock', 'anthropic', 0);
        CREATE TABLE sessions(
            id INTEGER PRIMARY KEY,
            provider_id INTEGER REFERENCES providers(id),
            created_at TEXT DEFAULT (datetime('now'))
        );
        INSERT INTO sessions VALUES(1, 1, '2026-09-11');
    ''')
    conn.commit()

    # 只读方式打开
    ro = sqlite3.connect(f'file:{db_path}?mode=ro', uri=True)
    tables = ro.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").fetchall()
    result = {'tables': {}, 'db_path': str(db_path), 'mode': 'ro'}
    for (t,) in tables:
        schema = ro.execute(f"SELECT sql FROM sqlite_master WHERE name='{t}'").fetchone()
        result['tables'][t] = schema[0] if schema else None
        count = ro.execute(f'SELECT COUNT(*) FROM "{t}"').fetchone()[0]
        result['tables'][t] = {'schema': schema[0] if schema else None, 'row_count': count}
    ro.close()
    print(json.dumps(result, indent=2, ensure_ascii=False))
    db_path.unlink()  # 清理
except Exception as e:
    print(json.dumps({'error': str(e)}))
